package ai.decisionos.aside;
import android.app.*;import android.webkit.*;import android.widget.*;import android.view.*;import android.text.InputType;import android.os.*;import org.json.*;
/** Native credential entry; the model never receives credentials. The task WebView stays parked. */
final class BackgroundSchoolLogin {
 final Activity a;final WebView web;final Handler h=new Handler(Looper.getMainLooper());int generation;boolean emailDone,portalDone,microsoftDone,fsDone;AlertDialog dialog;
 BackgroundSchoolLogin(Activity a,WebView web){this.a=a;this.web=web;}
 void status(String text){if(a instanceof GoalAgentActivity){NubiTossHomeUi home=((GoalAgentActivity)a).chat.companion.tossHome;if(home!=null)home.web.evaluateJavascript("window.NubiSchoolLoginStatus&&window.NubiSchoolLoginStatus("+JSONObject.quote(text)+")",null);}}
 void cancel(){generation++;h.removeCallbacksAndMessages(null);}
 static String microsoftAccount(String account){return account.contains("@")?account:account+"@unist.ac.kr";}
 static boolean accountAllowed(String account){return PortalCredentialCapture.schoolIdentity(account)||account.matches("[A-Za-z0-9._-]{1,100}");}
 AlertDialog show(){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);int p=Ui.dp(a,20);box.setPadding(p,p,p,p);EditText account=new EditText(a),password=new EditText(a);account.setHint("UNIST 학교 계정");password.setHint("학교 비밀번호");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);account.setSingleLine();password.setSingleLine();account.setSaveEnabled(false);password.setSaveEnabled(false);account.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);password.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);box.addView(account);box.addView(password);
  try{JSONObject saved=new NativeCredentialVault(a).load("school");if(saved!=null)account.setText(saved.optString("account"));}catch(Exception ignored){}
  AlertDialog d=new AlertDialog.Builder(a).setTitle("학교 계정 연결").setView(box).setNegativeButton("취소",null).setPositiveButton("연결",null).create();d.getWindow();d.setOnShowListener(v->{d.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);d.getButton(-1).setOnClickListener(button->{String id=account.getText().toString().trim();if(!accountAllowed(id)||password.length()==0){account.setError("학교 계정을 확인해 주세요");return;}try{new NativeCredentialVault(a).save("school",new JSONObject().put("account",id).put("secret",password.getText().toString()));password.setText("");account.setText("");d.dismiss();status("학교 계정을 확인하고 있어요");PortalCredentialCapture.authorizeSchool(web);web.loadUrl("https://portal.unist.ac.kr/");emailDone=false;portalDone=false;microsoftDone=false;fsDone=false;int token=++generation;step(token,SystemClock.elapsedRealtime()+180000);}catch(Exception e){password.setError("학교 계정을 저장하지 못했어요");}});});d.setOnDismissListener(v->{password.setText("");account.setText("");});d.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);d.show();dialog=d;return d;
 }
 void step(int token,long end){if(token!=generation||a.isDestroyed())return;if(SystemClock.elapsedRealtime()>end){status("연결 확인이 지연되고 있어요. 학교 계정으로 연결을 다시 눌러 주세요");return;}String url=web.getUrl();if(url==null||!SchoolSignIn.allowed(url)){h.postDelayed(()->step(token,end),700);return;}try{JSONObject saved=new NativeCredentialVault(a).load("school");if(saved==null)return;
 String script="(()=>{const emailDone="+emailDone+",portalDone="+portalDone+",microsoftDone="+microsoftDone+",fsDone="+fsDone+";const account="+JSONObject.quote(url.startsWith("https://login.microsoftonline.com/")?microsoftAccount(saved.getString("account")):saved.getString("account"))+",secret="+JSONObject.quote(saved.getString("secret"))+";const visible=e=>!!e?.getClientRects().length&&!e.disabled;const set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;const fill=(e,v)=>{if(!e.value){set.call(e,v);e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));}return e.value===v;};if(location.origin==='https://login.microsoftonline.com'){const email=document.querySelector('#i0116'),next=document.querySelector('#idSIButton9');if(visible(email)&&visible(next)){if(emailDone)return 'waiting';if(!/@unist[.]ac[.]kr$/i.test(account))return 'school_email_required';if(fill(email,account)){next.click();return 'next';}return 'different_account';}const identity=(document.querySelector('#displayName')?.textContent||document.querySelector('.identity')?.textContent||'').trim(),pw=document.querySelector('#i0118');if(visible(pw)&&visible(next)){if(microsoftDone)return 'waiting';if(identity.toLowerCase()!==account.toLowerCase())return 'different_account';if(fill(pw,secret)){next.click();return 'microsoft_submitted';}}if(visible(next)&&/Stay signed in|로그인 상태를 유지/i.test(document.body.innerText)){next.click();return 'persist';}return 'waiting';}if(location.origin==='https://fs.unist.ac.kr'&&location.pathname==='/adfs/ls/'){const error=document.querySelector('#errorText');if(error&&visible(error)&&error.innerText.trim())return 'authentication_error';const user=document.querySelector('#customUserNameInput'),pw=document.querySelector('#passwordInput'),button=document.querySelector('#submitButton'),form=document.querySelector('#loginForm');if(!fsDone&&visible(user)&&visible(pw)&&visible(button)&&form&&new URL(form.action,location.href).origin===location.origin&&fill(user,account.replace(/@unist[.]ac[.]kr$/i,''))&&fill(pw,secret)){button.click();return 'fs_submitted';}return 'waiting';}if(location.origin==='https://portal.unist.ac.kr'){if(/로그아웃|log.?out/i.test(document.body.innerText)&&!document.querySelector('input[type=password]'))return 'authenticated';const pw=[...document.querySelectorAll('input[type=password]')].filter(visible);if(pw.length!==1)return 'waiting';const f=pw[0].form;if(!f||new URL(f.action||location.href,location.href).origin!==location.origin)return 'waiting';const users=[...f.querySelectorAll('input')].filter(e=>visible(e)&&/^(text|email)$/.test(e.type)&&/user|uid|login|account|id/i.test(e.name+' '+e.id));const buttons=[...f.querySelectorAll('button,input[type=submit],input[type=button]')].filter(visible).filter(e=>/^(로그인|login|log on)$/i.test((e.innerText||e.value||'').trim()));if(!portalDone&&users.length===1&&buttons.length===1&&fill(users[0],account)&&fill(pw[0],secret)){buttons[0].click();return 'portal_submitted';}}return 'waiting'})()";
 web.evaluateJavascript(script,r->{if(token!=generation)return;if("\"authenticated\"".equals(r)){status("포털 연결 완료 · 로그인 세션을 유지하고 있어요");WebSessionPolicy.checkpoint();generation++;return;}if("\"authentication_error\"".equals(r)){status("학교 인증에서 계정 정보를 확인해 달라고 안내했어요. 입력 정보를 확인해 주세요");generation++;return;}if("\"fs_submitted\"".equals(r)){fsDone=true;status("학교 인증 확인 중이에요");}if("\"next\"".equals(r))emailDone=true;if("\"portal_submitted\"".equals(r))portalDone=true;if("\"microsoft_submitted\"".equals(r))microsoftDone=true;if("\"school_email_required\"".equals(r)||"\"different_account\"".equals(r)){status("학교 이메일로 연결해 주세요");Toast.makeText(a,"학교 이메일로 연결해 주세요",Toast.LENGTH_LONG).show();generation++;return;}WebSessionPolicy.checkpoint();h.postDelayed(()->step(token,end),1800);});
 }catch(Exception ignored){generation++;}}
}
